import threading
import time
import json
import os
from collections import defaultdict

class UserSessionStore:
    """Хранилище сессий пользователей с TTL."""

    def __init__(self, ttl_seconds=3600):
        self._ttl = ttl_seconds
        self._sessions = {}
        self._locks = defaultdict(threading.Lock)
        self._cleanup_thread = threading.Thread(target=self._cleanup_loop, daemon=True)
        self._cleanup_thread.start()

    def create_session(self, user_id, data=None):
        session_id = self._generate_id()
        self._sessions[session_id] = {
            'user_id': user_id,
            'data': data or {},
            'created_at': time.time(),
            'expires_at': time.time() + self._ttl
        }
        return session_id

    def get_session(self, session_id):
        with self._locks[session_id]:
            session = self._sessions.get(session_id)
            if session is None:
                return None
            if time.time() > session['expires_at']:
                del self._sessions[session_id]
                return None
            session['expires_at'] = time.time() + self._ttl
            return dict(session)

    def update_session(self, session_id, data):
        with self._locks[session_id]:
            session = self._sessions.get(session_id)
            if session is None:
                return False
            session['data'].update(data)
            session['expires_at'] = time.time() + self._ttl
            return True

    def delete_session(self, session_id):
        with self._locks[session_id]:
            if session_id in self._sessions:
                del self._sessions[session_id]
                return True
            return False

    def get_active_sessions(self):
        now = time.time()
        result = []
        for sid, session in list(self._sessions.items()):
            if now <= session['expires_at']:
                result.append((sid, session['user_id']))
        return result

    def save_to_disk(self, filepath):
        with open(filepath, 'w') as f:
            json.dump(self._sessions, f)

    def load_from_disk(self, filepath):
        if not os.path.exists(filepath):
            return
        with open(filepath) as f:
            self._sessions = json.load(f)

    def _generate_id(self):
        import uuid
        return str(uuid.uuid4())

    def _cleanup_loop(self):
        while True:
            time.sleep(60)
            now = time.time()
            for sid, session in list(self._sessions.items()):
                if now > session['expires_at']:
                    del self._sessions[sid]


class RateLimiter:
    """Token bucket rate limiter."""

    def __init__(self, rate=10, burst=20):
        self.rate = rate
        self.burst = burst
        self.tokens = defaultdict(lambda: burst)
        self.last_refill = defaultdict(time.time)

    def allow(self, key):
        now = time.time()
        elapsed = now - self.last_refill[key]
        refill = elapsed * self.rate
        self.tokens[key] = min(self.burst, self.tokens[key] + refill)
        self.last_refill[key] = now
        if self.tokens[key] >= 1:
            self.tokens[key] -= 1
            return True
        return False

    def reset(self, key):
        self.tokens[key] = self.burst
        self.last_refill[key] = time.time()
